/**
 * Encrypted operation envelope for the durable buffer (Sync v2, decision:
 * encrypted by default). The signaling server stores and forwards only the
 * opaque `sealed` form — it never sees plaintext op content or the key.
 *
 * One key per board ("content key"), generated by the first editor to
 * provision the board, AES-256-GCM with a fresh 12-byte IV per operation.
 * `keyId` is a stable fingerprint so a client holding the right key can pick
 * its own records out of a mixed buffer without decrypting everything.
 *
 * Key distribution rides the board's authenticated peer channel (a content-key
 * frame exchanged after device admission); viewers never receive it. Boards
 * without a provisioned key simply do not use the buffer — local journal
 * durability is unaffected.
 */
import { sha256Digest } from "./snapshotV2";

export type SealedOp = {
  v: 1;
  opId: string;
  keyId: string;
  /** base64url 12-byte AES-GCM IV. */
  iv: string;
  /** base64url ciphertext of the canonical op JSON (UTF-8). */
  ct: string;
};

export type BoardContentKey = { keyId: string; key: CryptoKey };

const b64url = (bytes: ArrayBuffer | Uint8Array) => {
  const view = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  return btoa(String.fromCharCode(...view)).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
};
const unb64url = (value: string) => Uint8Array.from(atob(value.replace(/-/g, "+").replace(/_/g, "/")), (c) => c.charCodeAt(0));

export async function generateBoardContentKey(): Promise<BoardContentKey> {
  const key = await crypto.subtle.generateKey({ name: "AES-GCM", length: 256 }, true, ["encrypt", "decrypt"]);
  return { keyId: await keyIdOf(key), key };
}

export async function keyIdOf(key: CryptoKey): Promise<string> {
  const spki = await crypto.subtle.exportKey("raw", key);
  const digest = await sha256Digest(b64url(spki));
  return digest.slice("sha256:".length, "sha256:".length + 16);
}

export async function exportBoardContentKey(key: CryptoKey): Promise<string> {
  return b64url(await crypto.subtle.exportKey("raw", key));
}

export async function importBoardContentKey(material: string): Promise<BoardContentKey> {
  const key = await crypto.subtle.importKey("raw", unb64url(material) as BufferSource, "AES-GCM", true, ["encrypt", "decrypt"]);
  return { keyId: await keyIdOf(key), key };
}

export async function sealOp(key: BoardContentKey, opId: string, plaintext: unknown): Promise<SealedOp> {
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const ct = await crypto.subtle.encrypt({ name: "AES-GCM", iv: iv as BufferSource, additionalData: new TextEncoder().encode(opId) }, key.key, new TextEncoder().encode(JSON.stringify(plaintext)) as BufferSource);
  return { v: 1, opId, keyId: key.keyId, iv: b64url(iv), ct: b64url(ct) };
}

export async function openOp(key: BoardContentKey, sealed: SealedOp): Promise<unknown> {
  if (sealed.keyId !== key.keyId) throw new Error("Buffered op belongs to a different content key");
  const plain = await crypto.subtle.decrypt({ name: "AES-GCM", iv: unb64url(sealed.iv) as BufferSource, additionalData: new TextEncoder().encode(sealed.opId) }, key.key, unb64url(sealed.ct) as BufferSource);
  return JSON.parse(new TextDecoder().decode(plain));
}
